    created_at, updated_at
) VALUES (
    #{sessionId}, #{executionId}, #{rootEventId}, #{state}, #{currentSegmentId},
    #{createdAt}, #{updatedAt}
)

INSERT INTO t_session_execution_segments (
    session_id, execution_id, segment_id, segment_ordinal,
    trigger_event_id, trigger_event_seq, state, created_at, updated_at
) VALUES (
    #{sessionId}, #{executionId}, #{segmentId}, #{segmentOrdinal},
    #{triggerEventId}, #{triggerEventSeq}, #{state}, #{createdAt}, #{updatedAt}
)

mapper.select:
SELECT session_id, execution_id, root_event_id, state, current_segment_id,
       pending_tool_call_id, stop_event_id, terminal_event_id,
       UPPER(terminal_reason) AS terminal_reason, created_at, updated_at, terminal_at
FROM t_session_executions
WHERE session_id = #{sessionId}
  AND execution_id = #{executionId}
  AND root_event_id = #{rootEventId}
  AND current_segment_id = #{segmentId}

SELECT session_id, execution_id, segment_id, segment_ordinal,
       trigger_event_id, trigger_event_seq, state, terminal_event_id,
       terminal_event_seq, UPPER(terminal_reason) AS terminal_reason,
       created_at, updated_at
FROM t_session_execution_segments
WHERE session_id = #{sessionId}
  AND execution_id = #{executionId}
  AND segment_id = #{segmentId}
FOR UPDATE

mapper.insert:
INSERT INTO t_session_execution_segment_events (
    session_id, execution_id, segment_id, event_id, event_seq
) VALUES (
    #{sessionId}, #{executionId}, #{segmentId}, #{eventId}, #{eventSeq}
)

mapper.update:
UPDATE t_session_execution_segments
SET state = 'CLOSED',
    terminal_event_id = #{terminalEventId},
    terminal_event_seq = #{terminalEventSeq},
    terminal_reason = #{terminalReason},
    updated_at = #{updatedAt}
WHERE session_id = #{sessionId}
  AND execution_id = #{executionId}
  AND segment_id = #{segmentId}
  AND state = 'OPEN'

UPDATE t_session_executions
SET state = 'CONFIRMING',
    pending_tool_call_id = #{toolCallId},
    updated_at = #{updatedAt}
WHERE session_id = #{sessionId}
  AND execution_id = #{executionId}
  AND current_segment_id = #{segmentId}
  AND state = 'RUNNING'
  AND stop_event_id IS NULL

UPDATE t_session_executions
SET state = 'STOPPING',
    stop_event_id = #{stopEventId},
    updated_at = #{updatedAt}
WHERE session_id = #{sessionId}
  AND execution_id = #{executionId}
  AND current_segment_id = #{segmentId}
  AND state IN ('RUNNING', 'CONFIRMING')
  AND stop_event_id IS NULL

mapper.select:
SELECT COALESCE(MAX(segment_ordinal), 0) + 1
FROM t_session_execution_segments
WHERE session_id = #{sessionId}
  AND execution_id = #{executionId}

mapper.insert:
INSERT INTO t_session_tool_confirmations (
    session_id, execution_id, confirmation_event_id, previous_segment_id,
    segment_id, tool_call_id, result, deny_message, state, created_at
) VALUES (
    #{sessionId}, #{executionId}, #{confirmationEventId}, #{previousSegmentId},
    #{segmentId}, #{toolCallId}, LOWER(CAST(#{result} AS VARCHAR)),
    #{denyMessage}, #{state}, #{createdAt}
)

mapper.update:
UPDATE t_session_executions
SET state = 'RUNNING',
    current_segment_id = #{segmentId},
    pending_tool_call_id = NULL,
    updated_at = #{updatedAt}
WHERE session_id = #{sessionId}
  AND execution_id = #{executionId}
  AND current_segment_id = #{previousSegmentId}
  AND state = 'CONFIRMING'
  AND pending_tool_call_id = #{toolCallId}
  AND stop_event_id IS NULL

UPDATE t_session_tool_confirmations decision
SET state = 'CLAIMED',
    claimed_at = #{claimedAt}
WHERE decision.session_id = #{sessionId}
  AND decision.execution_id = #{executionId}
  AND decision.previous_segment_id = #{previousSegmentId}
  AND decision.tool_call_id = #{toolCallId}
  AND decision.state = 'PENDING'
  AND EXISTS (
      SELECT 1
      FROM t_session_executions execution
      WHERE execution.session_id = decision.session_id
        AND execution.execution_id = decision.execution_id
        AND execution.root_event_id = #{rootEventId}
        AND execution.current_segment_id = decision.segment_id
        AND execution.state = 'RUNNING'
        AND execution.stop_event_id IS NULL
  )

mapper.select:
SELECT session_id, execution_id, confirmation_event_id, previous_segment_id,
       segment_id, tool_call_id, UPPER(result) AS result, deny_message,
       state, created_at, claimed_at, completed_at
FROM t_session_tool_confirmations
WHERE session_id = #{sessionId}
  AND execution_id = #{executionId}
  AND previous_segment_id = #{previousSegmentId}
  AND tool_call_id = #{toolCallId}
  AND state = 'CLAIMED'

mapper.update:
UPDATE t_session_tool_confirmations
SET state = 'COMPLETED',
    completed_at = #{completedAt}
WHERE session_id = #{sessionId}
  AND execution_id = #{executionId}
  AND confirmation_event_id = #{confirmationEventId}
  AND state = 'CLAIMED'

UPDATE t_session_executions
SET state = 'TERMINAL',
    pending_tool_call_id = NULL,
    terminal_event_id = #{terminalEventId},
    terminal_reason = #{terminalReason},
    updated_at = #{terminalAt},
    terminal_at = #{terminalAt}
WHERE session_id = #{sessionId}
  AND execution_id = #{executionId}
  AND current_segment_id = #{segmentId}
  AND state IN ('RUNNING', 'CONFIRMING', 'STOPPING')
